var content = K.Stack(9,
    new Grid
    {
        ColumnDefinitions = new ColumnDefinitions("*,Auto"),
        Children =
        {
            K.Stack(2, K.Text("Routines", "arc-heading"),
                K.Caption("Scheduled agents that report back on their own")),
            K.Row(6, newRoutine, K.IconBtn("settings", "Routine settings"))
        }
    },
    list,      // 句子式例行行
    status);

return K.Surface(new Border { Child = content, MaxWidth = 820 }, new Thickness(20, 12, 20, 12));

var switchControl = K.Toggle(string.Empty, item.Enabled, on =>
{
    item.Enabled = on;
    Render();
    status.Text = on ? $"{item.Name} enabled." : $"{item.Name} paused. Its schedule is kept.";
});
AutomationProperties.SetName(switchControl, $"{item.Name} enabled");

var nameButton = K.Btn(item.Name, ArcButtonVariant.Ghost, ArcButtonSize.Sm, ToggleOpen,
    trailingIcon: isOpen ? "chevron-up" : "chevron-down");

var head = K.Stack(5,
    K.Row(8, switchControl, K.Stack(1, nameButton, K.Caption($"{item.Schedule} · {item.Countdown}"))),
    K.RowWrap(6, connectorDiscs, K.Chip(item.Destination, icon: "hash"), K.Chip(item.Model, icon: "cpu"), runNow));

var body = K.Stack(6, head);
if (isOpen)
{
    body.Children.Add(K.Divider(4));
    body.Children.Add(K.Stack(3, K.Caption("Latest report"), K.Text(item.Report, "arc-body-sm", 520)));
    body.Children.Add(K.Segmented(new[]
    {
        ("hourly", "Hourly"), ("daily", "Daily"), ("weekdays", "Weekdays"), ("weekly", "Weekly")
    }, "daily", value => status.Text = $"Frequency set to {value}."));
}
